// Store the inbound Outlook reply on the verified NAF ticket.
// Matches the dashboard payload: sentAt/id/createdAt are omitted because staging generates them.
// The multipart attachments field is always present, including for text-only replies.
function newReplyId() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.floor(Math.random() * 16);
    return (c === 'x' ? r : (r & 3) | 8).toString(16);
  });
}

function safeDiagnostic(value, token) {
  let text;
  try { text = typeof value === 'string' ? value : JSON.stringify(value); }
  catch { text = '[unserializable error]'; }
  return String(text || '').split(token).join('[REDACTED]')
    .replace(/Bearer\s+[^\s"',}]+/gi, 'Bearer [REDACTED]')
    .replace(/([?&]emailData=)[^\s"<>]*/gi, '$1[REDACTED]')
    .slice(0, 3000);
}

const inputs = $input.all();
const output = [];

for (let i = 0; i < inputs.length; i++) {
  const item = inputs[i];
  const email = item.json || {};
  const ticketId = String(email.ticketId || '');
  const requestId = newReplyId();

  if (!email.matchedTicket || !/^\d+$/.test(ticketId)) {
    throw new Error('Reply upload requires a verified internal numeric ticket ID.');
  }

  const authenticated = $('Read Authentication Token').itemMatching(i).json;
  if (String(authenticated.messageId || '') !== String(email.messageId || '')) {
    throw new Error('Authentication item does not match the Outlook reply.');
  }

  const token = authenticated.authToken;
  if (!token) throw new Error('Missing authentication token for reply upload.');

  const keys = Object.keys(item.binary || {});
  if (keys.length !== Number(email.attachmentCount || 0) || keys.length > 12) {
    throw new Error('Missing or excessive reply attachments; email remains unread.');
  }

  const emailData = {
    subject: String(email.subject || ''),
    message: String(email.description || ''),
    senderName: String(email.fullName || ''),
    senderEmail: String(email.email || ''),
    senderType: 'Customer',
    direction: 'inbound',
    attachments: []
  };

  const boundary = '----NAFReply' + Date.now().toString(36) + Math.random().toString(36).slice(2);
  const parts = [];
  let totalBytes = 0;
  const filenames = [];

  for (const key of keys) {
    const meta = item.binary[key] || {};
    const bytes = await this.helpers.getBinaryDataBuffer(i, key);
    if (!Buffer.isBuffer(bytes) || bytes.length === 0) {
      throw new Error('Empty or unreadable reply attachment.');
    }

    totalBytes += bytes.length;
    if (totalBytes > 20 * 1024 * 1024) {
      throw new Error('Reply attachments exceed 20 MiB.');
    }

    const filename = String(meta.fileName || key).replace(/[\r\n"\\]/g, '_').slice(0, 180);
    const mime = String(meta.mimeType || 'application/octet-stream').replace(/[\r\n]/g, '');
    filenames.push(filename);
    parts.push(Buffer.from('--' + boundary + '\r\n' +
      'Content-Disposition: form-data; name="attachments"; filename="' + filename + '"\r\n' +
      'Content-Type: ' + mime + '\r\n\r\n', 'utf8'));
    parts.push(bytes, Buffer.from('\r\n'));
  }

  // Staging accepts text-only replies when the empty multipart field is present.
  if (keys.length === 0) {
    parts.push(Buffer.from('--' + boundary + '\r\n' +
      'Content-Disposition: form-data; name="attachments"\r\n\r\n\r\n', 'utf8'));
  }

  parts.push(Buffer.from('--' + boundary + '--\r\n'));
  const body = Buffer.concat(parts);

  let response;
  try {
    response = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://staging-api.naf-cloudsystem.de/api/NAFWebsite/issue/' + encodeURIComponent(ticketId) + '/emails',
      qs: { emailData: JSON.stringify(emailData) },
      headers: {
        Accept: 'application/json',
        Authorization: 'Bearer ' + token,
        'Content-Type': 'multipart/form-data; boundary=' + boundary,
        'Content-Length': String(body.length)
      },
      body,
      json: false,
      timeout: 60000
    });
  } catch (err) {
    const status = err?.statusCode ?? err?.httpCode ?? err?.response?.statusCode ?? err?.response?.status ?? 'not available';
    const details = err?.response?.body ?? err?.response?.data ?? err?.error ?? err?.description ?? '';
    throw new Error('Reply upload failed; HTTP status: ' + String(status) +
      '; cause: ' + safeDiagnostic(err?.message || err, token) +
      '; API response: ' + (safeDiagnostic(details, token) || '(empty)') +
      '; ticket: ' + ticketId + '; request ID: ' + requestId +
      '; attachments: ' + keys.length + '; multipart bytes: ' + body.length +
      '. Email remains unread. Do not automatically repeat this POST.');
  }

  let parsed = response;
  if (typeof response === 'string') {
    try { parsed = JSON.parse(response); }
    catch { parsed = { rawBody: response }; }
  }

  output.push({
    json: {
      storedReplyResponse: parsed ?? null,
      originalMessageId: email.messageId,
      ticketId,
      submittedReplyId: requestId,
      uploadedAttachmentCount: keys.length,
      uploadedAttachmentNames: filenames
    },
    pairedItem: { item: i }
  });
}

return output;
